"""Minimal faithful shim of the `atomicwrites` package (verification only).

Implements the one API pytest 5.2.3 uses: atomic_write(path, mode=..., overwrite=...)
used as a context manager yielding a writable file object; on clean exit the
temp file replaces the target (os.replace), on error it is removed.
"""
import os
import tempfile


class AtomicWriter(object):
    def __init__(self, path, mode="w", overwrite=False, **open_kwargs):
        self._path = path
        self._mode = mode
        self._overwrite = overwrite
        self._open_kwargs = open_kwargs
        self._fp = None
        self._temp_path = None

    def open(self):
        if self._fp is not None:
            raise RuntimeError("AtomicWriter already open")
        d = os.path.dirname(os.path.abspath(self._path))
        fd, temp_path = tempfile.mkstemp(dir=d, prefix=".atomicwrites-")
        self._temp_path = temp_path
        self._fp = os.fdopen(fd, self._mode, **self._open_kwargs)
        return self

    def __enter__(self):
        return self.open()

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._fp.close()
        if exc_type is None:
            if not self._overwrite and os.path.exists(self._path):
                self.rollback()
                return False
            os.replace(self._temp_path, self._path)
            return False
        self.rollback()
        return False

    def rollback(self):
        try:
            os.unlink(self._temp_path)
        except OSError:
            pass

    def __getattr__(self, name):
        return getattr(self.__dict__["_fp"], name)


def atomic_write(path, mode="w", overwrite=False, **open_kwargs):
    return AtomicWriter(path, mode=mode, overwrite=overwrite, **open_kwargs)

